function ctxNorm(v){
  return String(v||'').normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/²/g,'2').replace(/⁺/g,'').replace(/[^a-zA-Z0-9]+/g,' ').trim().toLowerCase();
}
function ctxUniqueSteps(arr,total){
  return Array.from(new Set((arr||[]).map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<total))).sort((a,b)=>a-b);
}
function contextSourceFromOpener(opener){
  let lessonIndex=null, moduleId=null;
  try{
    const lesson=opener&&opener.closest?opener.closest('.lesson'):null;
    if(lesson&&/^lesson-\d+$/.test(lesson.id)) lessonIndex=Number(lesson.id.slice(7));
    if(typeof MODULES!=='undefined'&&MODULES[currentModule]) moduleId=MODULES[currentModule].id;
  }catch(e){}
  return {moduleId,lessonIndex};
}
function ctxModule(moduleId,term){
  if(typeof MODULES==='undefined') return null;
  if(moduleId){ const m=MODULES.find(x=>x.id===moduleId); if(m) return m; }
  const view=document.getElementById('view-module');
  if(view&&view.classList.contains('active')&&MODULES[currentModule]) return MODULES[currentModule];
  try{
    if(term&&typeof TERM_FIG!=='undefined'&&TERM_FIG[term]&&String(TERM_FIG[term]).indexOf('mod:')===0){
      const m=MODULES.find(x=>x.id===String(TERM_FIG[term]).slice(4)); if(m) return m;
    }
    if(term&&typeof termNode==='function'){ const ref=termNode(term); const m=ref&&MODULES.find(x=>x.id===ref.a); if(m) return m; }
  }catch(e){}
  return MODULES[currentModule]||null;
}
function ctxExact(map,term){
  const n=ctxNorm(term); if(!n||!map) return null;
  for(const k of Object.keys(map)) if(ctxNorm(k)===n) return map[k];
  return null;
}
function ctxOverviewRelation(moduleId,term,partId,chain){
  const a=(CONTEXT_ANATOMY[moduleId]||{})[partId]; if(a) return Object.assign({kind:a.steps&&a.steps.length?'direct':'context'},a);
  const t=ctxExact(CONTEXT_TERMS[moduleId]||{},term); if(t) return Object.assign({kind:t.steps&&t.steps.length?'direct':'context'},t);
  return {steps:[],kind:'context',note:'Este componente se relaciona ao processo geral, mas não recebeu uma etapa direta na visão resumida do módulo.'};
}
function ctxTopicData(m,lessonIndex){
  try{
    const c=typeof CHAIN!=='undefined'&&CHAIN[m.id]&&CHAIN[m.id][lessonIndex];
    if(!c||!Array.isArray(c.s)||!c.s.length) return null;
    return {chain:c.s,hinge:Number.isInteger(c.h)?c.h:Math.floor(c.s.length/2),lead:m.lessons[lessonIndex]?m.lessons[lessonIndex].t:'Mecanismo do tópico'};
  }catch(e){return null;}
}
function ctxTopicRelation(moduleId,lessonIndex,term){
  const byLesson=(CONTEXT_TOPIC_TERMS[moduleId]||{})[String(lessonIndex)]||{};
  const rel=ctxExact(byLesson,term);
  return rel?Object.assign({kind:rel.steps&&rel.steps.length?'direct':'context'},rel):null;
}
function ctxKindLabel(kind){
  return kind==='distributed'?'ao longo do tópico':kind==='parallel'?'ramo relacionado':kind==='contrast'?'contraste':kind==='context'?'contexto do tópico':'etapa direta';
}
function ctxSummary(kind,hasSteps){
  if(kind==='distributed') return 'Ver como atravessa o mecanismo';
  if(kind==='parallel') return 'Ver o ramo relacionado';
  if(kind==='contrast') return 'Comparar com o mecanismo';
  if(kind==='context'||!hasSteps) return 'Ver como se relaciona ao mecanismo';
  return 'Ver onde entra no mecanismo';
}
function ctxStepLabel(steps,total,kind,scope,lessonIndex){
  const prefix=scope==='topic'?'tópico '+(lessonIndex+1)+' · ':'';
  if(kind==='distributed') return prefix+'ao longo da sequência';
  if(kind==='parallel') return prefix+'processo paralelo';
  if(kind==='contrast') return prefix+'contraste';
  if(!steps.length) return prefix+'relação geral';
  if(steps.length===1) return prefix+'etapa '+(steps[0]+1)+' de '+total;
  const nums=steps.map(n=>n+1); return prefix+'etapas '+nums.slice(0,-1).join(', ')+' e '+nums[nums.length-1];
}
function ctxEscape(v){ return String(v||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function renderContextMechanism(opts){
  const host=document.getElementById('tm-mech'); if(!host) return;
  const m=ctxModule(opts&&opts.moduleId,(opts&&opts.term)||(opts&&opts.label));
  if(!m){host.innerHTML='';host.hidden=true;_ctxMechanism=null;return;}
  const label=(opts&&opts.label)||(opts&&opts.term)||'Este componente';
  const li=Number.isInteger(opts&&opts.lessonIndex)?opts.lessonIndex:null;
  const topic=li!==null?ctxTopicData(m,li):null;
  let scope='overview', d=null, rel=null;
  if(topic){
    rel=ctxTopicRelation(m.id,li,(opts&&opts.term)||label);
    if(rel){scope='topic';d=topic;}
  }
  if(!d){
    d=typeof functionalData==='function'?functionalData(m):null;
    if(d) rel=ctxOverviewRelation(m.id,(opts&&opts.term)||label,(opts&&opts.partId)||'',d.chain);
  }
  if(!d||!Array.isArray(d.chain)||!d.chain.length){host.innerHTML='';host.hidden=true;_ctxMechanism=null;return;}
  rel=rel||{steps:[],kind:'context'};
  const kind=rel.kind||((rel.steps||[]).length?'direct':'context');
  const steps=ctxUniqueSteps(rel.steps,d.chain.length);
  const primary=Number.isInteger(rel.primary)&&steps.includes(rel.primary)?rel.primary:(steps[0]??Math.max(0,d.hinge||0));
  _ctxMechanism={moduleId:m.id,label,chain:d.chain,steps,primary,selected:primary,note:rel.note||'',scope,lessonIndex:li,kind};
  const note=rel.note||(steps.length?'A etapa destacada mostra a participação deste elemento na sequência.':'O conceito organiza ou contextualiza o tópico, sem corresponder a uma única etapa.');
  const seq=d.chain.map((text,i)=>`<li><button type="button" class="ctx-step${steps.includes(i)?' relevant':''}${i===primary?' active':''}" data-ctx-step="${i}" onclick="selectContextMechanismStep(${i})" aria-current="${i===primary?'step':'false'}"><span class="ctx-num">${i+1}</span><span class="ctx-text">${ctxEscape(text)}</span>${steps.includes(i)?'<span class="ctx-here">este elemento</span>':''}</button></li>`).join('');
  host.style.setProperty('--mc',m.color); host.hidden=false;
  const openLabel=scope==='topic'?'Ir ao tópico e destacar esta sequência →':'Abrir mecanismo completo a partir daqui →';
  host.innerHTML=`<details class="ctx-mech"><summary><span><span class="ctx-k">Mecanismo · ${scope==='topic'?'tópico':'visão geral'}</span><b>${ctxSummary(kind,steps.length)}</b></span><span class="ctx-badge">${ctxEscape(ctxStepLabel(steps,d.chain.length,kind,scope,li||0))}</span></summary><div class="ctx-body"><div class="ctx-relation ${kind}">${ctxEscape(ctxKindLabel(kind))}</div><p class="ctx-note">${ctxEscape(note)}</p><ol class="ctx-seq">${seq}</ol><div class="ctx-detail"><span id="ctx-detail-k">Etapa ${primary+1} de ${d.chain.length}</span><p id="ctx-detail-text">${ctxEscape(d.chain[primary])}</p></div><button type="button" class="ctx-open" onclick="openContextMechanismFull()">${openLabel}</button><div class="ctx-live" id="ctx-live" aria-live="polite"></div></div></details>`;
}
function selectContextMechanismStep(i){
  if(!_ctxMechanism) return; const n=Math.max(0,Math.min(_ctxMechanism.chain.length-1,Number(i)||0)); _ctxMechanism.selected=n;
  const host=document.getElementById('tm-mech'); if(!host) return;
  host.querySelectorAll('.ctx-step').forEach((b,idx)=>{const on=idx===n;b.classList.toggle('active',on);b.setAttribute('aria-current',on?'step':'false');});
  const k=document.getElementById('ctx-detail-k'),t=document.getElementById('ctx-detail-text'),live=document.getElementById('ctx-live');
  if(k)k.textContent='Etapa '+(n+1)+' de '+_ctxMechanism.chain.length; if(t)t.textContent=_ctxMechanism.chain[n]; if(live)live.textContent='Etapa '+(n+1)+': '+_ctxMechanism.chain[n];
}
function openContextMechanismFull(){
  if(!_ctxMechanism||typeof MODULES==='undefined') return;
  const mi=typeof modIndex==='function'?modIndex(_ctxMechanism.moduleId):MODULES.findIndex(m=>m.id===_ctxMechanism.moduleId); if(mi<0)return;
  const target=_ctxMechanism.selected, scope=_ctxMechanism.scope, li=_ctxMechanism.lessonIndex, marked=_ctxMechanism.steps.slice();
  try{if(typeof closeTermModal==='function')closeTermModal(true);}catch(e){} try{if(typeof closeSearch==='function')closeSearch(true);}catch(e){}
  if(currentModule!==mi||!document.getElementById('view-module').classList.contains('active')) openModule(mi);
  setTimeout(()=>{
    try{
      if(scope==='topic'&&Number.isInteger(li)){
        const lesson=document.getElementById('lesson-'+li), box=lesson&&lesson.querySelector('.chain');
        if(box){
          box.classList.add('ctx-jumped'); const nodes=box.querySelectorAll('.cstep');
          nodes.forEach((el,i)=>el.classList.toggle('ctx-jump',marked.includes(i)));
          box.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});
          const focus=nodes[target]||nodes[marked[0]]; if(focus){focus.setAttribute('tabindex','-1');focus.focus({preventScroll:true});}
          setTimeout(()=>{box.classList.remove('ctx-jumped');nodes.forEach(el=>el.classList.remove('ctx-jump'));},2400);
        }
      }else{
        setVisualMode('functional');
        // Aguarda o layout vertical ficar visível e deixa a própria etapa ativa
        // ser a referência final da rolagem. Evita que o painel desfaça o centro.
        requestAnimationFrame(()=>requestAnimationFrame(()=>selectFunctionalStep(target,false)));
      }
    }catch(e){}
  },90);
}
